#region "FormPlugin"
public class FormPlugin : System.MarshalByRefObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaFormPlugin
{

    public override object InitializeLifetimeService()
    {
        // returning null here will prevent the lease manager
        // from deleting the Object.
        return null;
    }

    public void SetupBeforeHandlers(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
    }

    public void Setup(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
		var journalSetsForm = (JiwaFinancials.Jiwa.JiwaJournalSetsUI.MainForm)JiwaForm;

		// Add the tool to the toolbar
	    Infragistics.Win.UltraWinToolbars.RibbonGroup group;
	    Infragistics.Win.UltraWinToolbars.ButtonTool buttonTool;

	    buttonTool = new Infragistics.Win.UltraWinToolbars.ButtonTool("ID_RecordImportFromCSV");
	    buttonTool.SharedProps.Caption = "Import From CSV";
	    journalSetsForm.UltraToolbarsManager1.Tools.Add(buttonTool);

	    group = journalSetsForm.UltraToolbarsManager1.Ribbon.Tabs["Main"].Groups["Actions"];
	    group.Tools.AddTool("ID_RecordImportFromCSV");
	    journalSetsForm.UltraToolbarsManager1.Ribbon.Tabs["Main"].Groups["Actions"].Tools["ID_RecordImportFromCSV"].InstanceProps.PreferredSizeOnRibbon = Infragistics.Win.UltraWinToolbars.RibbonToolSize.Normal;
	    journalSetsForm.UltraToolbarsManager1.Toolbars["Toolbar"].Tools.InsertTool(journalSetsForm.UltraToolbarsManager1.Toolbars["Toolbar"].Tools["ID_RecordNew"].Index + 1, "ID_RecordImportFromCSV");
		
		journalSetsForm.UltraToolbarsManager1.ToolClick += journalSetsForm_UltraToolbarsManager1_ToolClick;			
    }
	
	public void journalSetsForm_UltraToolbarsManager1_ToolClick(object sender, Infragistics.Win.UltraWinToolbars.ToolClickEventArgs e)
	{
		if(e.Tool.Key == "ID_RecordImportFromCSV")
		{
			string fullFileName = GetCSVFileName();
			if(fullFileName != null && fullFileName.Trim().Length > 0)
			{
				//Create a new journal set
				JiwaFinancials.Jiwa.JiwaJournalSetsUI.MainForm journalSetsForm = (JiwaFinancials.Jiwa.JiwaJournalSetsUI.MainForm)((Infragistics.Win.UltraWinToolbars.UltraToolbarsManager)sender).DockWithinContainer;
				journalSetsForm.NewRecord();
				journalSetsForm.JournalSet.SetType = JiwaFinancials.Jiwa.JiwaJournalSets.JournalSet.SetTypes.Pending;

				//Get the CSV data
				List<ImportLine> lines = System.IO.File.ReadAllText(fullFileName).FromCsv<List<ImportLine>>();

				JiwaFinancials.Jiwa.JiwaJournalSets.Line journalSetLine = null;
				foreach(ImportLine line in lines)
				{
					SetLineDefaults(line);				
					
					journalSetLine = journalSetsForm.Manager.CollectionItemFactory.CreateCollectionItem<JiwaFinancials.Jiwa.JiwaJournalSets.Line>();
					
					journalSetLine.GLAccount.ReadRecordFromAccountNo(line.AccountNo);
					journalSetLine.TransPostDateTime = line.Date;
					journalSetLine.Reference = line.Reference;
					journalSetLine.DebitAmount = line.Debit;
					journalSetLine.CreditAmount = line.Credit;
					journalSetLine.BASCode = (JiwaFinancials.Jiwa.JiwaJournalSets.Line.BASCodes)line.BASCode;
					journalSetLine.Remark = line.Remark;
					
					journalSetsForm.JournalSet.Lines.Add(journalSetLine);
				}
				
				MessageBox.Show(string.Format("{0} imported.", fullFileName), "Journal Set CSV Import", MessageBoxButtons.OK, MessageBoxIcon.Information, MessageBoxDefaultButton.Button1);
			}
		}
	}
	
	public string GetCSVFileName()
	{
		//Show open CSV dialog
		string FileFilter = "CSV Files (*.csv)|*.csv|All Files (*.*)|*.*";
		
		System.Windows.Forms.OpenFileDialog DialogOpen = new System.Windows.Forms.OpenFileDialog();
		DialogOpen.Title = "Journal Set Import";
		DialogOpen.Filter = FileFilter;
		DialogOpen.FileName = "";
		if (DialogOpen.ShowDialog() == System.Windows.Forms.DialogResult.OK && DialogOpen.FileName.Trim().Length > 0)
			return DialogOpen.FileName;
		else
			return "";		
	}	
	public void SetLineDefaults(ImportLine Line)
	{
		//Set defaults	
		if(Line.AccountNo == null)
			Line.AccountNo = "";
		
		if(Line.Description == null)
			Line.Description = "";		
		
		if(Line.Date == null)
			Line.Date = DateTime.Now;
		
		if(Line.Reference == null)
			Line.Reference = "";		
		
		if(Line.Debit == null)
			Line.Debit = 0;
		
		if(Line.Credit == null)
			Line.Credit = 0;		
		
		if(Line.BASCode == null)
			Line.BASCode = 0;
		
		if(Line.Remark == null)
			Line.Remark = "";			
	}	
}
#endregion

