#region "POCO"
[DataContract]
public class ImportLine
{
	public enum BASCodes
	{
	    No_Code = 0,
	    Sales_G1 = 1,
	    Exports_G2 = 2,
	    Sales_GST_Free_G3 = 3,
	    Input_Tax_Sales_G4 = 4,
	    Not_Used_G5 = 5,
	    Not_Used_G6 = 6,
	    Sales_Adjustments_G7 = 7,
	    Not_Used_G8 = 8,
	    Not_Used_G9 = 9,
	    Capital_Purchases_G10 = 10,
	    Purchases_G11 = 11,
	    Not_Used_G12 = 12,
	    Purchases_For_Sales_G13 = 13,
	    Purchases_GST_Free_G14 = 14,
	    Purchases_Private_G15 = 15,
	    Not_Used_G16 = 16,
	    Not_Used_G17 = 17,
	    Purchase_Adjustments_G18 = 18,
	    Not_Used_G19 = 19,
	    Not_Used_G20 = 20,
	    Salaries_Paid_W1 = 21,
	    Salary_Deductions_W2 = 22,
	    Investment_Deductions_W3 = 23,
	    No_ABN_W4 = 24,
	    Wine_Equalisation_Payable_1C = 25,
	    Wine_Equalisation_Refundable_1D = 26,
	    Luxury_Car_Payable_1E = 27,
	    Luxury_Car_Refundable_1F = 28,
	    WST_Credit_1G = 29,
	    Pay_As_You_Go_4 = 30
	}
	
	[DataMember]
	public string AccountNo {get; set;}
	[DataMember]
	public string Description {get; set;}
	[DataMember]
	public DateTime Date {get; set;}
	[DataMember]
	public string Reference {get; set;}
	[DataMember]
	public decimal Debit {get; set;}
	[DataMember]
	public decimal Credit {get; set;}
	[DataMember(Name="BAS Code")]
	public BASCodes BASCode {get; set;}
	[DataMember]
	public string Remark {get; set;}
	
	public ImportLine()
	{
		AccountNo = "";
		Description = "";
		Date = DateTime.Now;
		Reference = "";	
		Debit = 0;
		Credit = 0;
		BASCode = 0;
		Remark = "";
	}
}
#endregion
